using BragaEventos.Models; using BragaEventos.Services; namespace BragaEventos.Views; public partial class ResumoPage:ContentPage {public ResumoPage(Evento evento){InitializeComponent();BindingContext=evento;}protected override async void OnAppearing(){base.OnAppearing();Opacity=0;TranslationY=18;await Task.WhenAll(this.FadeTo(1,350),this.TranslateTo(0,0,400,Easing.CubicOut));}async void SalvarAgenda(object sender,EventArgs e){if(BindingContext is Evento evento){EventoStore.Salvar(evento);await DisplayAlert("Salvo","Evento adicionado à agenda do dispositivo.","OK");}}
async void Voltar(object sender,EventArgs e)=>await Navigation.PopAsync();}